CREATE TABLE `promo_codes` (
  `id` varchar(64) NOT NULL,
  `code` varchar(20) NOT NULL,
  `description` varchar(500) DEFAULT NULL,
  `type` varchar(10) NOT NULL,
  `value` decimal(10,2) NOT NULL,
  `max_discount` decimal(10,2) DEFAULT NULL,
  `min_order` decimal(10,2) NOT NULL DEFAULT 0.00,
  `starts_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `ends_at` timestamp NULL DEFAULT NULL,
  `total_limit` int(11) DEFAULT NULL,
  `per_customer_limit_once` tinyint(1) NOT NULL DEFAULT 0,
  `audience` varchar(20) NOT NULL DEFAULT 'EVERYONE',
  `channel` varchar(10) NOT NULL DEFAULT 'BOTH',
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `usage_count` int(11) NOT NULL DEFAULT 0,
  `created_by` varchar(64) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp(3) NOT NULL DEFAULT current_timestamp(3),
  PRIMARY KEY (`id`),
  UNIQUE KEY `promo_codes_code_key` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
